fn hstack(a: Vec<f32>, b: Vec<f32>) -> Vec<f32> {
    // Pre-allocate a new Vec with enough capacity for both inputs
    let mut result = Vec::with_capacity(a.len() + b.len());
    // Extend with elements from `a`
    result.extend(a.into_iter());
    // Extend with elements from `b`
    result.extend(b.into_iter());
    result
}

